1→import { ImapFlow } from "imapflow";
import type { TrackingStore } from "../data/store.ts";
import { parseDispatchEmail, type ParsedDispatch } from "./email.ts";
import { messageText } from "./mime.ts";

export interface MailboxConfig {
  host: string;
  port: number;
  secure: boolean;
10→  user: string;
  password: string;
  mailbox: string;
}

export interface ScanItem {
  subject: string;
  from: string;
  outcome: "creado" | "ya-estaba" | "sin-producto" | "ignorado";
  detail: string;
20→  parsed?: ParsedDispatch;
}

export interface ScanReport {
  examined: number;
  created: number;
  already: number;
  unmatched: number;
  ignored: number;
  items: ScanItem[];
30→}

export function configFromEnv(): MailboxConfig | null {
  const host = process.env.MAIL_HOST;
  const user = process.env.MAIL_USER;
  const password = process.env.MAIL_PASSWORD;
  if (!host || !user || !password) return null;
  return {
    host,
    port: Number(process.env.MAIL_PORT ?? 993),
40→    secure: (process.env.MAIL_SECURE ?? "true") !== "false",
    user,
    password,
    mailbox: process.env.MAIL_MAILBOX ?? "INBOX",
  };
}

export function publicConfig(config: MailboxConfig | null): { configured: boolean; host?: string; port?: number; secure?: boolean; user?: string; mailbox?: string } {
  if (!config) return { configured: false };
  return { configured: true, host: config.host, port: config.port, secure: config.secure, user: config.user, mailbox: config.mailbox };
50→}

function clientOptions(config: MailboxConfig) {
  return {
    host: config.host,
    port: config.port,
    secure: config.secure,
    doSTARTTLS: config.secure ? undefined : false,
    auth: { user: config.user, pass: config.password },
    logger: false as const,
60→    disableAutoIdle: true,
    connectionTimeout: 12_000,
    greetingTimeout: 12_000,
    socketTimeout: 20_000,
  };
}

function scrub(error: unknown, password: string): string {
  const message = error instanceof Error ? error.message : "No se pudo leer el buzón.";
  return password ? message.split(password).join("***") : message;
70→}

export async function connectMailbox(config: MailboxConfig): Promise<void> {
  const client = new ImapFlow(clientOptions(config));
  client.on("error", () => undefined);
  try {
    await client.connect();
    await client.logout();
  } catch (error) {
    throw new Error(scrub(error, config.password));
80→  }
}

function headerLine(raw: string, name: string): string {
  const head = raw.split(/\r?\n\r?\n/)[0] ?? "";
  return head.match(new RegExp(`^${name}:\\s*(.+)$`, "im"))?.[1]?.trim() ?? "";
}

export function applyMessage(store: TrackingStore, raw: string, subject = "", from = ""): ScanItem {
